1	import { createContext, useContext, useState } from 'react'
2	
3	const AppContext = createContext()
4	
5	export function AppProvider({ children }) {
6	  const [theme, setTheme] = useState('light')
7	
8	  return (
9	    <AppContext.Provider value={{ theme, setTheme }}>
10	      {children}
11	    </AppContext.Provider>
12	  )
13	}
14	
15	export function useAppContext() {
16	  const context = useContext(AppContext)
17	  if (!context) {
18	    throw new Error('useAppContext must be used within AppProvider')
19	  }
20	  return context
21	}
