import type { Metadata } from 'next'
import { headers } from 'next/headers'
import { PushButton } from '@/components/PushButton'
import type { Post } from '@/types/blog'

export const metadata: Metadata = {
  title: 'Home - My Blog',
  description: 'Welcome to my blog homepage',
  openGraph: {
    title: 'Home - My Blog',
  },
}

export default async function HomePage() {
  // `getServerSideProps({ req })` -> the async `headers()` API.
  const requestHeaders = await headers()
  const userAgent = requestHeaders.get('user-agent') ?? ''

  // `cache: 'no-store'` keeps the per-request freshness getServerSideProps had.
  const res = await fetch('https://jsonplaceholder.typicode.com/posts?_limit=5', {
    cache: 'no-store',
  })
  const posts: Post[] = await res.json()

  const timestamp = new Date().toISOString()

  return (
    <div>
      <h1>Welcome to My Blog</h1>
      <p>Server-side rendered at: {timestamp}</p>
      <p>Your user agent: {userAgent}</p>

      <h2>Recent Posts</h2>
      <ul>
        {posts.map((post) => (
          <li key={post.id}>
            <a href={`/blog/${post.id}`}>{post.title}</a>
          </li>
        ))}
      </ul>

      <PushButton href="/blog">View All Posts</PushButton>
    </div>
  )
}

